import http from 'k6/http';import {check} from 'k6';import {baseURL,scenarioOptions} from '../lib/config.js';import {routeSuccess} from '../lib/metrics.js';import {uniqueNamespace} from '../lib/data.js';
function header(r,n){let v=r.headers[n]||r.headers.Etag;for(const k of Object.keys(r.headers))if(k.toLowerCase()===n.toLowerCase())v=r.headers[k];return Array.isArray(v)?v[0]:v}export const options=scenarioOptions('state',['route_success']);export default function(){const ns=uniqueNamespace('state'),url=`${baseURL()}/state/${ns}/items`,body=JSON.stringify({id:'b',name:'beta'}),h={'Content-Type':'application/json','Idempotency-Key':`key-${ns}`};const pair=http.batch([['POST',url,body,{headers:h}],['POST',url,body,{headers:h}]]),etag=header(pair[0],'ETag');let ok=check(pair,{'state concurrent create statuses 201':r=>r.every(x=>x.status===201),'state idempotent replay body equal':r=>r[0].body===r[1].body,'state idempotent replay location equal':r=>header(r[0],'Location')===header(r[1],'Location'),'state idempotent replay ETag equal':r=>header(r[0],'ETag')===header(r[1],'ETag')});const conflict=http.post(url,JSON.stringify({id:'other',name:'conflict'}),{headers:h}),isolated=http.post(`${baseURL()}/state/${ns}-other/items`,body,{headers:h});ok=check(conflict,{'state idempotency payload conflict 409':r=>r.status===409})&&check(isolated,{'state idempotency namespace isolated 201':r=>r.status===201})&&ok;http.post(url,JSON.stringify({id:'a',name:'alpha'}),{headers:{'Content-Type':'application/json'}});const list=http.get(url);ok=check(list,{'state list status 200':r=>r.status===200,'state list contains two items':r=>r.json().length===2,'state list stable sorted order':r=>r.json()[0].id==='a'&&r.json()[1].id==='b'})&&ok;const item=`${url}/b`,missing=http.put(item,JSON.stringify({name:'x'}),{headers:{'Content-Type':'application/json'}}),weak=http.put(item,JSON.stringify({name:'x'}),{headers:{'Content-Type':'application/json','If-Match':'W/"v1"'}}),multi=http.put(item,JSON.stringify({name:'x'}),{headers:{'Content-Type':'application/json','If-Match':'"v1", "v2"'}}),stale=http.put(item,JSON.stringify({name:'x'}),{headers:{'Content-Type':'application/json','If-Match':'"v9"'}});ok=check(missing,{'state missing If-Match 428':r=>r.status===428})&&check(weak,{'state weak ETag rejected 412':r=>r.status===412})&&check(multi,{'state multiple ETag rejected 412':r=>r.status===412})&&check(stale,{'state stale ETag rejected 412':r=>r.status===412})&&ok;const put=http.put(item,JSON.stringify({name:'updated'}),{headers:{'Content-Type':'application/json','If-Match':etag}}),next=header(put,'ETag');ok=check(put,{'state valid ETag update 200':r=>r.status===200,'state ETag advances to v2':()=>next==='"v2"','state updated name persisted':r=>r.json().name==='updated'})&&ok;const del=http.del(item);ok=check(del,{'state delete status 204':r=>r.status===204,'state delete body empty':r=>!r.body||r.body.length===0})&&check(http.get(item),{'state deleted item returns 404':r=>r.status===404})&&ok;routeSuccess.add(ok,{route_family:'state',operation:'extended_lifecycle'});}
